// 获取Token公共类
// TokenServiceTest .java
import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;


import org.apache.http.Consts;
import org.apache.http.HttpResponse;
import org.apache.http.HttpStatus;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;


import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.Charset;


/**
 * 获取accessToken
 *
 */
public class TokenServiceTest {
    /**
     * @param domain 域名
     * @param clientId clientId
     * @param clientSecret clientSecret
     * @return accessToken
     */
    public static String getToken(String domain, String clientId, String clientSecret) {
        String token = null;
        CloseableHttpClient httpClient = HttpClients.createDefault();
        HttpPost post = new HttpPost(domain + "/oauth2/v1/token");
        try {
            JSONObject keyString = new JSONObject();
            keyString.put("client_id", clientId);
            keyString.put("client_secret", clientSecret);
            keyString.put("grant_type", "client_credentials");


            StringEntity entity = new StringEntity(keyString.toString(), Charset.forName("UTF-8"));
            entity.setContentEncoding("UTF-8");
            entity.setContentType("application/json");
            post.setEntity(entity);
            HttpResponse response = httpClient.execute(post);
            int statusCode = response.getStatusLine().getStatusCode();
            if (statusCode == HttpStatus.SC_OK) {
                BufferedReader br =
                    new BufferedReader(new InputStreamReader(response.getEntity().getContent(), Consts.UTF_8));
                String result = br.readLine();
                JSONObject object = JSON.parseObject(result);
                token = object.getString("access_token");
            }


        } catch (Exception e) {
            throw new RuntimeException("Get Token Exception");
        } finally {
            post.releaseConnection();
            try {
                httpClient.close();
            } catch (IOException e) {
                throw new RuntimeException("Close httpClient Exception");
            }
        }
        return token;
    }
}


// UploadObjectTest.java
import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;


import lombok.Builder;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;


import org.apache.commons.lang3.StringUtils;
import org.apache.http.Consts;
import org.apache.http.HttpStatus;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPut;
import org.apache.http.client.utils.URIBuilder;
import org.apache.http.entity.ContentType;
import org.apache.http.entity.InputStreamEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.junit.Ignore;


import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.RandomAccessFile;
import java.security.MessageDigest;


import javax.xml.bind.DatatypeConverter;


/**
 * 上传文件REST API示例代码
 */
@Slf4j
@Ignore
public class UploadObjectTest {
    /**
     * 上传文件
     *
     * @param storageUrl 云存储url
     * @param param 上传文件接口入参
     * @param offset 文件偏移量，普通上传置为-1即可。如果是分片上传，则需要填具体的值。
     * @param fileSize 文件总大小
     * @param inputStreamEntity 文件流
     * @throws Exception 异常
     */
    public static void uploadObject(String storageUrl, UploadObjectParam param, long offset, long fileSize,
        InputStreamEntity inputStreamEntity) throws Exception {
        URIBuilder uriBuilder = new URIBuilder(storageUrl + param.getBucketName() + "/" + param.getObjectName());
        HttpPut httpPut = new HttpPut(uriBuilder.build());
        httpPut.setHeader("productId", param.getProjectId());
        httpPut.setHeader("client_id", param.getClientId());
        httpPut.setHeader("Authorization", "Bearer " + param.getToken());
        httpPut.setHeader("X-Agc-File-Size", String.valueOf(fileSize));
        if (StringUtils.isNotEmpty(param.getSha256())) {
            // 文件的sha256，断点续传、分片上传时为必填
            httpPut.setHeader("X-Agc-Sha256", param.getSha256());
        }
        if (offset >= 0) {
            // 文件偏移，，断点续传、分片上传时的起始位置非零时为必填
            httpPut.setHeader("X-Agc-File-Offset", String.valueOf(offset));
        }
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
            httpPut.setEntity(inputStreamEntity);
            CloseableHttpResponse httpResponse = httpClient.execute(httpPut);
            int statusCode = httpResponse.getStatusLine().getStatusCode();
            if (statusCode == HttpStatus.SC_OK) {
                BufferedReader br =
                    new BufferedReader(new InputStreamReader(httpResponse.getEntity().getContent(), Consts.UTF_8));
                String result = br.readLine();
                JSONObject object = JSON.parseObject(result);
                log.info("uploadObject result:{}", object.toJSONString());
                br.close();
            }
            httpResponse.close();
        }
    }


    /**
     * 分片上传
     *
     * @throws Exception 异常
     */
    public void chunkClient() throws Exception {
        String clientToken = TokenServiceTest.getToken("https://connect-api.cloud.huawei.com/api/",
            "84903XXXXXX32064", "00E5CCADB655891XXXXXXXXXXXX8CDCC83ACF22");
        // 分片的大小
        int chunkSize = 1024 * 1024;


        // 获取文件输入流
        File file = new File(getClass().getClassLoader().getResource("run.log").getFile());
        // 获取文件总大小
        long fileSize = file.length();
        // 计算分片数量
        int chunkCount = (int) Math.ceil((double) fileSize / chunkSize);


        UploadObjectParam param = UploadObjectParam.builder()
            .projectId("73643XXXXXX61998")
            .clientId("84903XXXXXX32064")
            .token(clientToken)
            .bucketName("test-q36q0")
            .objectName("temp/run.log")
            .sha256(getSha256(file.getPath()))
            .build();
        // 创建一个RandomAccessFile用来读取文件
        try (RandomAccessFile raf = new RandomAccessFile(file, "r")) {
            // 逐个分片上传
            for (int i = 0; i < chunkCount; i++) {
                // 计算当前分片的起始位置和长度
                long offset = i * chunkSize;
                long length = Math.min(chunkSize, fileSize - offset);
                // 构造请求实体，包含分片数据
                InputStream inputStream = new InputStreamSegment(raf, offset, length);
                InputStreamEntity entity = new InputStreamEntity(inputStream, length);
                uploadObject("https://ops-server-drcn.agcstorage.link/v0/", param, offset, file.length(), entity);
            }
        }
    }


    /**
     * 普通文件上传
     *
     * @throws Exception
     */
    public void client() throws Exception {
        String clientToken = TokenServiceTest.getToken("https://connect-api.cloud.huawei.com/api/",
            "84903XXXXXX32064", "00E5CCADB655891XXXXXXXXXXXX8CDCC83ACF22");
        UploadObjectParam param = UploadObjectParam.builder()
            .projectId("401697XXXXXX27846")
            .clientId("84412XXXXXX3648")
            .token(clientToken)
            .bucketName("test-q36q0")
            .objectName("temp/hello.txt")
            .build();
        File file = new File(getClass().getClassLoader().getResource("hello.txt").getFile());
        FileInputStream fis = new FileInputStream(file);
        InputStreamEntity inputStreamEntity =
            new InputStreamEntity(fis, file.length(), ContentType.APPLICATION_OCTET_STREAM);
        uploadObject("https://ops-server-drcn.agcstorage.link/v0/", param, -1, file.length(), inputStreamEntity);
    }


    // 获取文件的sha256值
    private static String getSha256(String filePath) throws Exception {
        FileInputStream fileInputStream = new FileInputStream(filePath);
        MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");
        byte[] buffer = new byte[1024];
        int bytesRead = 0;
        while ((bytesRead = fileInputStream.read(buffer)) != -1) {
            messageDigest.update(buffer, 0, bytesRead);
        }
        return DatatypeConverter.printHexBinary(messageDigest.digest());
    }


    public static void main(String[] args) throws Exception {
        // 文件上传
        new UploadObjectTest().client();


        // 分片上传
        new UploadObjectTest().chunkClient();
    }


    @Builder
    @Getter
    static class UploadObjectParam {
        // 项目ID
        String projectId;


        // 客户端ID
        String clientId;


        // clientToken
        String token;


        // 云存储实例名
        String bucketName;


        // 文件名，如果包含 '/' ，则认为是路径分隔符。如：temp/hello.jpg，则会将文件hello.jpg上传到对应存储实例的temp目录下。
        String objectName;


        // 文件的sha256，断点续传、分片上传时为必填
        String sha256;
    }


    static class InputStreamSegment extends InputStream {
        private RandomAccessFile raf;


        private long offset;


        private long length;


        private long position;


        public InputStreamSegment(RandomAccessFile raf, long offset, long length) {
            this.raf = raf;
            this.offset = offset;
            this.length = length;
            position = 0;
        }


        @Override
        public int read() throws IOException {
            if (position >= length) {
                return -1;
            }
            raf.seek(offset + position);
            int result = raf.read();
            if (result >= 0) {
                position++;
            }
            return result;
        }


        @Override
        public int read(byte[] b, int off, int len) throws IOException {
            if (position >= length) {
                return -1;
            }
            raf.seek(offset + position);
            int bytesToRead = (int) Math.min(len, length - position);
            int bytesRead = raf.read(b, off, bytesToRead);
            if (bytesRead >= 0) {
                position += bytesRead;
            }
            return bytesRead;
        }


        @Override
        public void close() throws IOException {
        }
    }
}


